def batch_notify(customer_ids, event, **context):
    sent = 0
    failed = []
    for customer_id in customer_ids:
        try:
            notify_customer(customer_id, event, **context)
            sent += 1
        except Exception:
            failed.append(customer_id)
    return {"sent": sent, "failed": failed}

